/**
 * Types shared with the web app. The schema types come straight from the API's OpenAPI spec
 * (src/api/v1.d.ts, generated by `npm run gen:api`), so a change in the API shows up here as a
 * type error. The app's own session endpoints return the same shapes.
 */
import type { components } from "./v1";

type S = components["schemas"];

export type Address = S["Address"];
export type Approval = S["Approval"];
export type Agent = S["Agent"];
export type Folder = "inbox" | "sent" | "drafts" | "archive" | "spam" | "trash";
export type ListFolder = Folder | "starred";

export type MessageSummary = S["MessageSummary"] & {
  /** Set when one of your agents wrote it. */
  sentByAgentId?: string | null;
};

export interface Attachment { id: string; filename: string; contentType: string; sizeBytes: number; available: boolean }

export interface Message extends MessageSummary {
  cc: Address[];
  bcc: Address[];
  replyTo: string | null;
  text: string;
  html: string | null;
  attachments: Attachment[];
}

export interface MessagePage { messages: MessageSummary[]; nextCursor: string | null }
export interface ThreadView { message: Message; thread: Message[] }

export interface MailboxOverview {
  id: string;
  address: string;
  displayName: string;
  usedBytes: number;
  quotaMb: number;
  kind?: "person" | "agent";
  folders: Partial<Record<Folder, { total: number; unread: number }>>;
}

export type Role = "owner" | "admin" | "member";

export interface Me {
  user: { id: string; email: string; name: string; emailVerified: boolean; twoFactor: boolean; platformAdmin: boolean };
  organization: { id: string; name: string; plan: string; isDemo: boolean; role: Role; timezone: string; country: string } | null;
}

export interface SendInput {
  mailboxId: string;
  to: string[];
  cc?: string[];
  subject: string;
  text: string;
  inReplyToId?: string;
}

export interface SendResult { messageId: string; status?: string; [k: string]: unknown }

// ---------------------------------------------------------------- work management

export type TaskStatus = "todo" | "doing" | "done";
export type Priority = "none" | "low" | "medium" | "high" | "urgent";
export type AssigneeId = `member:${string}` | `agent:${string}`;

export interface Assignee { id: AssigneeId; type: "member" | "agent"; name: string; email: string | null }

/** A task as GET /api/tasks returns it. */
export interface Task {
  id: string;
  ref: string;
  projectId: string | null;
  number: number;
  title: string;
  notes: string;
  statusId: string | null;
  statusName: string;
  statusColor: string | null;
  status: TaskStatus;
  assignee: { type: "member" | "agent"; id: string; name: string; email: string | null } | null;
  assigneeId: AssigneeId | null;
  priority: Priority;
  labels: string[];
  start: string | null;
  due: string | null;
  parentId: string | null;
  position: number;
  source: { threadId: string | null; messageId: string | null; from: string | null; subject: string | null } | null;
  subtasks: { total: number; done: number };
  commentCount: number;
  completedAt: string | null;
  createdBy: { type: string; id: string };
  createdAt: string;
  updatedAt: string;
  version: number;
}

export interface TaskComment { id: string; taskId: string; body: string; author: { type: string; id: string; name: string | null }; createdAt: string }

export interface TaskThreadItem {
  id: string;
  mailboxId?: string;
  direction: "inbound" | "outbound";
  from: { address: string; name: string | null };
  subject: string;
  date: string;
  latestText: string;
  byAgent: boolean;
}

export interface TaskActivity { id: string; actor: { type: string; id: string; name: string | null }; verb: string; data: Record<string, unknown>; at: string }

export interface TaskDetail {
  task: Task;
  subtasks: Task[];
  comments: TaskComment[];
  thread: TaskThreadItem[];
  activity: TaskActivity[];
  docs: { id: string; title: string; updatedAt: string }[];
  contacts: { id: string; name: string | null; email: string | null }[];
}

/** One stretch of time on a task: a running or stopped timer, or a manual entry. */
export interface TimeEntry {
  id: string;
  taskId: string | null;
  task: { id: string; ref: string; title: string } | null;
  projectId: string | null;
  person: { type: "member" | "agent"; id: string; name: string };
  startedAt: string;
  endedAt: string | null;
  running: boolean;
  seconds: number;
  note: string;
  billable: boolean;
  source: "timer" | "manual";
}

export interface TimeLog { taskId: string; minutes: number; date?: string; note?: string }

/** Fields GET /api/tasks/:id adds on top of the v1 TaskDetail shape. Optional so older servers still work. */
export interface TaskExtras {
  time?: { totalSeconds: number; entries: TimeEntry[] };
  blockedBy?: Task[];
  blocking?: Task[];
}
export type TaskView = TaskDetail & TaskExtras;

export interface MeetingSource { type: "thread" | "task" | "contact"; id: string }

export interface Meeting {
  id: string;
  title: string;
  startsAt: string;
  durationMin: number;
  endsAt: string;
  status: string;
  source: MeetingSource | null;
  invitees: string[];
  /** The meeting page in the web app (needs a MyMail sign in). */
  joinUrl: string;
  /** The guest page: works in any browser with no account. */
  guestUrl: string;
  videoEnabled: boolean;
}

export interface MeetingCreate {
  title?: string;
  startsAt?: string;
  durationMin?: number;
  source?: MeetingSource;
  invitees?: string[];
  sendInvites?: boolean;
}

export interface TaskQuery {
  status?: TaskStatus;
  threadId?: string;
  projectId?: string;
  assignee?: "me" | "none" | AssigneeId;
  q?: string;
  includeSubtasks?: boolean;
}

export interface TaskCreate {
  title: string;
  notes?: string;
  status?: TaskStatus;
  due?: string | null;
  priority?: Priority;
  labels?: string[];
  projectId?: string;
  assigneeId?: AssigneeId | null;
  parentId?: string;
  source?: { messageId?: string; threadId?: string };
}

export interface TaskPatch {
  title?: string;
  notes?: string;
  status?: TaskStatus;
  statusId?: string;
  due?: string | null;
  priority?: Priority;
  labels?: string[];
  assigneeId?: AssigneeId | null;
  position?: number;
  version?: number;
}

export interface Project {
  id: string;
  name: string;
  key: string;
  color: string | null;
  statuses: { id: string; name: string; category: TaskStatus; color: string | null; position: number }[];
  counts?: Record<string, number>;
}

export interface Change { seq: number; entity: string; id: string; op: string; version: number; at: string }
export interface ChangePage { changes: Change[]; cursor: number; more: boolean }

export interface AppNotification { id: string; type: string; entityType: string | null; entityId: string | null; title: string; read: boolean; createdAt: string }

/** What a push from the server carries: an event type and an id, nothing else. */
export type PushType = "message.received" | "approval.requested" | "task.assigned" | "task.commented" | "task.email_reply" | "task.due_soon" | "automation.status" | "automation.email";
export interface PushData { type: PushType | string; id: string }

// ---------------------------------------------------------------- kept in step with the API spec

/**
 * Compile-time checks against the generated spec (src/api/v1.d.ts, `npm run gen:api`): a field
 * added to or removed from the API's task shapes shows up here as a type error.
 */
type Assert<T extends true> = T;
type Same<A, B> = [A] extends [B] ? ([B] extends [A] ? true : false) : false;
type Within<A, B> = [A] extends [B] ? true : false;
export type SpecChecks = [
  Assert<Same<keyof S["Task"], keyof Task>>,
  Assert<Same<keyof S["TaskComment"], keyof TaskComment>>,
  Assert<Same<keyof NonNullable<S["TaskDetail"]>, keyof TaskDetail>>,
  Assert<Within<keyof Project, keyof S["Project"]>>,
  Assert<Within<keyof TaskCreate, keyof S["TaskCreate"] | "source">>,
  Assert<Within<keyof TaskPatch, keyof S["TaskPatch"]>>,
  Assert<Within<S["Task"]["status"], TaskStatus>>,
  Assert<Within<S["Task"]["priority"], Priority>>,
  Assert<Within<Pick<S["TimeEntry"], keyof TimeEntry>, TimeEntry>>,
];
